 float L(Rect r,string s,float x,float y,int sz,float op,Color c){text.fontSize=shadow.fontSize=sz;c.a*=op;text.normal.textColor=c;shadow.normal.textColor=new Color(0,0,0,op<=0?0:Mathf.Min(1,op+.22f));float w=text.CalcSize(new GUIContent(s)).x;GUI.Label(new Rect(r.x+x+1,r.y+y+1,w+3,sz+5),s,shadow);GUI.Label(new Rect(r.x+x,r.y+y,w+3,sz+5),s,text);return x+w+2;}
 void BoxDrag(int id,Rect r){if(!editMode.Value)return;GUI.Box(r,"");Event e=Event.current;if(e.type==EventType.MouseDown&&e.button==0&&r.Contains(e.mousePosition)){dragCluster=id;dragOffset=e.mousePosition-new Vector2(r.x,r.y);e.Use();}if(e.type==EventType.MouseDrag&&dragCluster==id){Vector2 p=e.mousePosition-dragOffset;p.x=Mathf.Clamp(p.x,-r.width+8,Screen.width-8);p.y=Mathf.Clamp(p.y,-r.height+6,Screen.height-6);if(id==1){popX.Value=p.x;popY.Value=Screen.height-p.y-r.height;}else if(id==2){statusX.Value=p.x;statusY.Value=Screen.height-p.y-r.height;}else{killX.Value=p.x;killY.Value=p.y;}e.Use();}if(e.type==EventType.MouseUp&&dragCluster==id){dragCluster=0;Config.Save();e.Use();}}
