 void DrawKills(Rect r,bool editing){BoxDrag(3,r);if(kills.Count==0){if(editing)L(r,"Scav  [AK]  PMC  ◎  187m",0,0,killSize.Value,killOpacity.Value,killNeutral.Value);return;}int start=Math.Max(0,kills.Count-killMax.Value),row=0;for(int i=kills.Count-1;i>=start;i--){KillLine k=kills[i];float age=Time.unscaledTime-k.Created,fade=Mathf.Clamp01((killLifetime.Value-age)/Mathf.Min(2f,killLifetime.Value));string s=killMode.Value=="Minimal"?$"{k.Killer}  [{k.Weapon}]  {k.Victim}":$"{k.Killer}  [{k.Weapon}]  {k.Victim}  {HitIcon(k.Hit)}  {Mathf.RoundToInt(k.Distance)}m";L(r,s,0,row*(killSize.Value+4),killSize.Value,killOpacity.Value*fade,killNeutral.Value);row++;}}
 string HitIcon(string h){h=(h??"").ToLowerInvariant();if(h.Contains("head"))return "◎";if(h.Contains("arm"))return "⌁";if(h.Contains("leg"))return "⌞";if(h.Contains("stomach"))return "◇";return "▣";}
 void Refresh(){try{object w=GetWorld();if(w==null){Outside();return;}IEnumerable ps=GetPlayers(w);if(ps==null){Outside();return;}inRaid=true;int p=0,s=0,b=0,r=0;object local=null;var seen=new HashSet<string>();foreach(object pl in ps){if(pl==null)continue;string id=PlayerId(pl);if(string.IsNullOrEmpty(id))id=pl.GetHashCode().ToString();seen.Add(id);bool alive=IsAlive(pl);string kind=Kind(pl);Vector3 pos=Position(pl);if(IsTrue(ReadMember(pl,"IsYourPlayer")))local=pl;else if(alive){if(kind=="Boss")b++;else if(kind=="Raider")r++;else if(kind=="PMC")p++;else s++;}Tracked old;if(tracked.TryGetValue(id,out old)&&old.Alive&&!alive)CaptureDeath(pl,old,ps);tracked[id]=new Tracked{Player=pl,Alive=alive,Pos=pos,Kind=kind,Weapon=Weapon(pl)};}foreach(string id in tracked.Keys.Where(x=>!seen.Contains(x)).ToList())tracked.Remove(id);pmc=p;scav=s;boss=b;reinforced=r;RefreshStatus(local);}catch(Exception ex){Logger.LogWarning("HUD refresh: "+ex.Message);}}
 void CaptureDeath(object victim,Tracked old,IEnumerable players){object hc=ReadMember(victim,"HealthController");object info=ReadMember(hc,"LastDamageInfo")??ReadMember(victim,"LastDamageInfo")??ReadMember(hc,"DamageInfo");object attacker=ReadMember(info,"Player")??ReadMember(info,"Attacker")??ReadMember(info,"SourcePlayer");string hit=(ReadMember(info,"BodyPart")??ReadMember(info,"HitBodyPart")??ReadMember(info,"BodyPartType"))?.ToString();float dist=0;string killer="Unknown",weapon="?";if(attacker!=null){killer=Kind(attacker);weapon=Weapon(attacker);dist=Vector3.Distance(Position(attacker),old.Pos);}else{object best=null;float bestD=9999;foreach(object p in players){if(p==null||ReferenceEquals(p,victim)||!IsAlive(p))continue;float d=Vector3.Distance(Position(p),old.Pos);if(d<bestD){bestD=d;best=p;}}if(best!=null&&bestD<150){killer=Kind(best);weapon=Weapon(best);dist=bestD;}}kills.Add(new KillLine{Killer=killer,Victim=old.Kind,Weapon=weapon,Hit=hit,Distance=dist,Created=Time.unscaledTime});}
 string Kind(object p){string role=Role(p),side=Side(p);if(IsBoss(role))return"Boss";if(IsReinforced(role))return"Raider";if(IsPmc(side))return"PMC";return"Scav";}string Weapon(object p){object hands=ReadMember(p,"HandsController"),item=ReadMember(hands,"Item");object tpl=ReadMember(item,"Template");string n=(ReadMember(tpl,"ShortName")??ReadMember(tpl,"Name")??ReadMember(item,"ShortName"))?.ToString();return string.IsNullOrEmpty(n)?"?":n;}
 Vector3 Position(object p){try{object tr=ReadMember(p,"Transform")??ReadMember(p,"transform");object v=ReadMember(tr,"position");if(v is Vector3)return(Vector3)v;}catch{}return Vector3.zero;}string PlayerId(object p){object pr=ReadMember(p,"Profile");return(ReadMember(pr,"Id")??ReadMember(pr,"ProfileId")??ReadMember(p,"ProfileId"))?.ToString();}
