 void Outside(){inRaid=false;pmc=scav=boss=reinforced=0;tracked.Clear();kills.Clear();if(!workAlways.Value&&!statusOutside.Value)mode=0;}void ApplyVersion(){try{foreach(var mb in Resources.FindObjectsOfTypeAll<MonoBehaviour>()){if(mb==null)continue;string tn=mb.GetType().Name;if(tn.IndexOf("LocalizedText",StringComparison.OrdinalIgnoreCase)<0&&tn.IndexOf("AlphaLabel",StringComparison.OrdinalIgnoreCase)<0)continue;string v=ReadText(mb);if(string.IsNullOrEmpty(v)||v.IndexOf("SPT",StringComparison.OrdinalIgnoreCase)<0)continue;if(mb.gameObject!=null&&mb.gameObject.activeSelf!=showVersion.Value)mb.gameObject.SetActive(showVersion.Value);}}catch{}}string ReadText(object o){foreach(string n in new[]{"text","Text","LabelText","_text"}){object v=ReadMember(o,n);if(v is string)return(string)v;}return null;}
 object GetWorld(){if(worldType==null)worldType=FindType("EFT.GameWorld")??FindTypeByName("GameWorld");if(worldType==null)return null;if(singletonType==null)singletonType=FindType("Comfort.Common.Singleton`1");if(singletonType==null)return null;if(singletonInstance==null)singletonInstance=singletonType.MakeGenericType(worldType).GetProperty("Instance",BindingFlags.Public|BindingFlags.Static);return singletonInstance?.GetValue(null,null);}IEnumerable GetPlayers(object w){if(playersMember==null){Type t=w.GetType();playersMember=(MemberInfo)t.GetProperty("RegisteredPlayers",BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic)??t.GetProperty("AllPlayers",BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic)??(MemberInfo)t.GetField("RegisteredPlayers",BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic);}object v=playersMember is PropertyInfo pi?pi.GetValue(w,null):(playersMember as FieldInfo)?.GetValue(w);return v as IEnumerable;}
 static bool IsAlive(object p){object h=ReadMember(p,"HealthController"),a=h!=null?ReadMember(h,"IsAlive"):ReadMember(p,"IsAlive");return!(a is bool)||(bool)a;}static string Side(object p){object pr=ReadMember(p,"Profile"),i=ReadMember(pr,"Info");return(ReadMember(i,"Side")??ReadMember(pr,"Side"))?.ToString();}static string Role(object p){object pr=ReadMember(p,"Profile"),i=ReadMember(pr,"Info"),s=ReadMember(i,"Settings")??ReadMember(pr,"Settings");return(ReadMember(s,"Role")??ReadMember(i,"Role"))?.ToString();}static bool IsPmc(string s)=>s!=null&&(s.IndexOf("USEC",StringComparison.OrdinalIgnoreCase)>=0||s.IndexOf("BEAR",StringComparison.OrdinalIgnoreCase)>=0);static bool IsBoss(string r)=>!string.IsNullOrEmpty(r)&&r.IndexOf("boss",StringComparison.OrdinalIgnoreCase)>=0;static bool IsReinforced(string role){if(string.IsNullOrEmpty(role))return false;string r=role.ToLowerInvariant();return r.Contains("follower")||r.Contains("pmcbot")||r.Contains("exusec")||r.Contains("raider")||r.Contains("rogue")||r.Contains("sectant")||r.Contains("arena")||r.Contains("assaultgroup");}
 static bool IsTrue(object v)=>v is bool&&(bool)v;static float?ReadFloat(object v){if(v==null)return null;try{return Convert.ToSingle(v);}catch{return null;}}static float?ReadFloatDeep(object o,string a,string b){object x=ReadMember(o,a);return ReadFloat(ReadMember(x,b))??ReadFloat(x);}static object ReadMember(object o,string n){if(o==null)return null;Type t=o.GetType();try{var p=t.GetProperty(n,BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic);if(p!=null)return p.GetValue(o,null);}catch{}try{var f=t.GetField(n,BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic);if(f!=null)return f.GetValue(o);}catch{}return null;}static Type FindType(string n){foreach(Assembly a in AppDomain.CurrentDomain.GetAssemblies())try{Type t=a.GetType(n,false);if(t!=null)return t;}catch{}return null;}static Type FindTypeByName(string n){foreach(Assembly a in AppDomain.CurrentDomain.GetAssemblies()){try{Type t=a.GetTypes().FirstOrDefault(x=>x.Name==n);if(t!=null)return t;}catch(ReflectionTypeLoadException e){Type t=e.Types?.FirstOrDefault(x=>x!=null&&x.Name==n);if(t!=null)return t;}catch{}}return null;}
